<script>
window.salesReturnRoutes = @json($salesReturnRoutes);
window.salesReturnInitial = {items:@json($initialItems), sourceType:@json(old('source_type', $document?->source_type ?? 'internal_invoice')), customerId:@json(old('customer_id', $document?->customer_id)), invoiceId:@json(old('invoice_id', $document?->invoice_id)), warehouses:@json($warehouses->map(fn($w)=>['id'=>$w->id,'name'=>$w->name,'type'=>$w->type])->values()), categories:@json($categories->values()), modelLists:@json($modelLists->values())};
</script>
<script>
document.addEventListener('DOMContentLoaded', () => {
try {
const routes=window.salesReturnRoutes, init=window.salesReturnInitial; const isAppliedEdit=@json($isAppliedEdit);
const state={type:init.sourceType||'internal_invoice',customer:{id:init.customerId||null,name:'',mobile:'',code:''},invoice:null,externalInvoiceDate:document.getElementById('externalInvoiceDate')?.value||'',internalItems:[],sazehItems:[],newProducts:[],newProduct:{prices:{purchase:null,sell:null,refund:null}},selectedCategories:[],selectedProducts:{},selectedVariants:new Map(),defaultDestinationWarehouseId:document.getElementById('defaultWarehouse')?.value||'',summary:{},items:init.items||[]};
let customerAbort, invoiceAbort, customerRequest=0, invoiceRequest=0, customerActive=-1, productAbort, categoryProductAbort, customerTimer, productTimer;
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const faDigits='۰۱۲۳۴۵۶۷۸۹', enDigits='0123456789';
const toPersianDigits=v=>String(v??'').replace(/[0-9]/g,d=>faDigits[d]);
const toEnglishDigits=v=>String(v??'').replace(/[۰-۹]/g,d=>String(faDigits.indexOf(d))).replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)));
const sanitizeMoneyInput=v=>toEnglishDigits(v).replace(/(ریال|تومان)/g,'').replace(/[,،.\s]/g,'').replace(/[^0-9]/g,'');
const moneyToInteger=v=>{const clean=sanitizeMoneyInput(v);return clean===''?null:parseInt(clean,10)};
const rawNumber=v=>moneyToInteger(v)??0;
const fmt=n=>{const value=typeof n==='number'?n:moneyToInteger(n);return value===null?'':value.toLocaleString('fa-IR')};
const moneyText=n=>(fmt(n)||'۰')+' ریال';
const fmtDate=d=>formatJalaliDate(d)||'—';
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const whName=id=>(init.warehouses.find(w=>String(w.id)===String(id))||{}).name||'—';
function gregorianToJalali(gy,gm,gd){const g_d_m=[0,31,59,90,120,151,181,212,243,273,304,334];let jy=(gy<=1600)?0:979;gy-=(gy<=1600)?621:1600;const gy2=(gm>2)?gy+1:gy;let days=(365*gy)+Math.floor((gy2+3)/4)-Math.floor((gy2+99)/100)+Math.floor((gy2+399)/400)-80+gd+g_d_m[gm-1];jy+=33*Math.floor(days/12053);days%=12053;jy+=4*Math.floor(days/1461);days%=1461;if(days>365){jy+=Math.floor((days-1)/365);days=(days-1)%365}const jm=(days<186)?1+Math.floor(days/31):7+Math.floor((days-186)/30);const jd=1+((days<186)?(days%31):((days-186)%30));return [jy,jm,jd]}
function normalizeGregorianDateInput(value){const normalized=toEnglishDigits(value||'').trim();const match=normalized.match(/^(\d{4})-(\d{2})-(\d{2})(?:[T\s]\d{2}:\d{2}(?::\d{2})?(?:\.\d+)?(?:Z|[+-]\d{2}:?\d{2})?)?$/);if(!match)return null;const year=+match[1],month=+match[2],day=+match[3],date=new Date(Date.UTC(year,month-1,day));if(date.getUTCFullYear()!==year||date.getUTCMonth()!==month-1||date.getUTCDate()!==day)return null;return `${match[1]}-${match[2]}-${match[3]}`}
function formatJalaliDate(value){const dateOnly=normalizeGregorianDateInput(value);if(!dateOnly)return'';const [gy,gm,gd]=dateOnly.split('-').map(Number);const [jy,jm,jd]=gregorianToJalali(gy,gm,gd);return toPersianDigits(`${jy}/${String(jm).padStart(2,'0')}/${String(jd).padStart(2,'0')}`)}
function jalaliToGregorian(jy,jm,jd){jy=Number(jy);jm=Number(jm);jd=Number(jd);jy+=(jy<100)?1400:0;let gy=jy<=979?621:1600;let y=jy<=979?jy:jy-979;let days=365*y+Math.floor(y/33)*8+Math.floor(((y%33)+3)/4)+78+jd+(jm<7?(jm-1)*31:(jm-7)*30+186);gy+=400*Math.floor(days/146097);days%=146097;if(days>36524){gy+=100*Math.floor(--days/36524);days%=36524;if(days>=365)days++}gy+=4*Math.floor(days/1461);days%=1461;if(days>365){gy+=Math.floor((days-1)/365);days=(days-1)%365}let gd=days+1;const sal=[0,31,((gy%4===0&&gy%100!==0)||gy%400===0)?29:28,31,30,31,30,31,31,30,31,30,31];let gm=1;while(gm<=12&&gd>sal[gm]){gd-=sal[gm];gm++}return [gy,gm,gd]}
function normalizeJalaliDateInput(value){let normalized=toEnglishDigits(value||'').trim();if(normalized==='')return'';const leadingTime=normalized.match(/^\d{1,2}:\d{2}(?::\d{2})?\s+(\d{4}[\/-]\d{1,2}[\/-]\d{1,2})$/);const trailingTime=normalized.match(/^(\d{4}[\/-]\d{1,2}[\/-]\d{1,2})\s+\d{1,2}:\d{2}(?::\d{2})?$/);if(leadingTime||trailingTime)normalized=(leadingTime||trailingTime)[1];const match=normalized.match(/^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})$/);if(!match)return null;const jy=+match[1],jm=+match[2],jd=+match[3];if(jm<1||jm>12||jd<1||jd>(jm<=6?31:jm<=11?30:30))return null;const [gy,gm,gd]=jalaliToGregorian(jy,jm,jd);const roundTrip=gregorianToJalali(gy,gm,gd);if(roundTrip[0]!==jy||roundTrip[1]!==jm||roundTrip[2]!==jd)return null;return `${gy}-${String(gm).padStart(2,'0')}-${String(gd).padStart(2,'0')}`}
function syncExternalDateDisplay(){const hidden=$('#externalInvoiceDate'),fa=$('#externalInvoiceDateFa');if(!hidden||!fa)return;const dateOnly=normalizeGregorianDateInput(hidden.value);hidden.value=dateOnly||'';state.externalInvoiceDate=hidden.value;fa.value=dateOnly?formatJalaliDate(dateOnly):''}
function syncExternalDateFromVisible(showError=false){const fa=$('#externalInvoiceDateFa'),hidden=$('#externalInvoiceDate'),err=$('#externalInvoiceDateError');if(!fa||!hidden)return true;const parsed=normalizeJalaliDateInput(fa.value);if(parsed===null){hidden.value='';state.externalInvoiceDate='';if(showError&&err)err.textContent='تاریخ را به‌شکل ۱۴۰۵/۰۵/۰۴ وارد کنید.';return false}hidden.value=parsed;state.externalInvoiceDate=parsed;fa.value=parsed?formatJalaliDate(parsed):'';if(err)err.textContent='';return true}
function initSazehInvoiceDatePicker(){const input=$('#externalInvoiceDateFa');if(!input)return;input.disabled=state.type!=='sazeh_hesab';input.readOnly=false;input.setAttribute('data-jdp-only-date','');if(input.dataset.datepickerInitialized==='1')return;input.dataset.datepickerInitialized='1';if(window.jalaliDatepicker){const dateOnlyOptions={selector:'#externalInvoiceDateFa',persianDigits:true,zIndex:3000,time:false,hideAfterChange:true};if(document.readyState==='loading')window.jalaliDatepicker.updateOptions(dateOnlyOptions);else window.jalaliDatepicker.startWatch(dateOnlyOptions);input.addEventListener('jdp:change',()=>syncExternalDateFromVisible(false));}}

function applySourceType(type, options = {}){const allowed=['internal_invoice','sazeh_hesab'];if(!allowed.includes(type))type='internal_invoice';state.type=type;const sourceTypeInput=$('#sourceTypeInput');if(sourceTypeInput)sourceTypeInput.value=type;$$('[name=source_choice]').forEach(r=>{r.checked=r.value===type});$$('[data-source-choice]').forEach(el=>el.classList.toggle('active',el.dataset.sourceChoice===type));$$('[data-source-panel]').forEach(panel=>{const active=panel.dataset.sourcePanel===type;panel.classList.toggle('d-none',!active);panel.querySelectorAll('input,select,textarea,button').forEach(input=>{input.disabled=!active});});$$('.sazeh-only').forEach(el=>el.classList.toggle('d-none',type!=='sazeh_hesab'));$$('.internal-only').forEach(el=>el.classList.toggle('d-none',type==='sazeh_hesab'));$$('.internal-col').forEach(el=>el.classList.toggle('d-none',type!=='internal_invoice'));initSazehInvoiceDatePicker();if(type==='internal_invoice'&&state.customer.id)loadCustomerInvoices(state.customer.id);if(!options.skipRender)renderItems();}
function syncSource(){applySourceType(state.type,{skipRender:false});}
function clearSourceSpecificState(previousType){state.invoice=null;$('#invoiceId').value='';if(previousType==='internal_invoice')resetInvoiceSelect('فاکتور داخلی فقط در نوع فاکتور داخلی بارگذاری می‌شود.', true);state.internalItems=[];state.sazehItems=[];state.selectedCategories=[];state.selectedProducts={};state.selectedVariants=new Map();}
function setSource(type){const previousType=state.type;if(!['internal_invoice','sazeh_hesab'].includes(type))type='internal_invoice';if(state.items.length&&!confirm('با تغییر نوع برگشت، اقلام فعلی پاک می‌شوند. ادامه می‌دهید؟')){applySourceType(previousType);return}if(type!==previousType){state.items=[];clearSourceSpecificState(previousType);}applySourceType(type);}

function decorateNewProductEditors(){if(isAppliedEdit)return;const seen=new Set();state.items.forEach((item,index)=>{const uuid=item.new_product_payload?.temporary_product_uuid;if(!uuid||seen.has(uuid))return;seen.add(uuid);const button=`<button class="btn btn-sm btn-outline-primary edit-new-product ms-1" data-uuid="${esc(uuid)}" type="button">ویرایش تعریف کالا</button>`;const desktop=$('#itemsTable tbody')?.children[index]?.lastElementChild;if(desktop&&!desktop.querySelector('.edit-new-product'))desktop.insertAdjacentHTML('afterbegin',button);const mobile=$('#mobileItems')?.children[index]?.querySelector('.d-flex');if(mobile&&!mobile.querySelector('.edit-new-product'))mobile.insertAdjacentHTML('beforeend',button)})}
function summary(){const qty=state.items.reduce((s,i)=>s+Number(i.return_quantity||0),0),amount=state.items.reduce((s,i)=>s+Number(i.refund_amount||0),0);$('[data-sum=rows]').textContent=state.items.length;$('[data-sum=qty]').textContent=fmt(qty);$('[data-sum=amount]').textContent=fmt(amount);$('[data-sum=warehouses]').textContent=whName(state.defaultDestinationWarehouseId)||'—';syncCompactItemsPayload();decorateNewProductEditors()}
function positionCustomerDropdown(){const box=$('#customerResults'), input=$('#customerSearch');if(!box||!input||box.classList.contains('d-none'))return;const r=input.getBoundingClientRect();const w=Math.min(r.width, window.innerWidth-16);box.style.width=w+'px';box.style.top=(r.bottom+6)+'px';box.style.left=Math.max(8, Math.min(r.left, window.innerWidth-w-8))+'px'}
function openCustomerDropdown(){const box=$('#customerResults');if(box.parentElement!==document.body)document.body.appendChild(box);box.classList.remove('d-none');$('#customerSearch')?.setAttribute('aria-expanded','true');positionCustomerDropdown()}
function closeCustomerDropdown(){const box=$('#customerResults');box?.classList.add('d-none');$('#customerSearch')?.setAttribute('aria-expanded','false')}
function renderCustomerStatus(html){$('#customerResults').innerHTML=html;openCustomerDropdown();customerActive=-1}
async function searchCustomers(q=''){q=(q||'').trim();if(customerAbort)customerAbort.abort();const req=++customerRequest;customerAbort=new AbortController();renderCustomerStatus(q.length<2?'<div class="p-2 sr-muted">نام، موبایل یا کد مشتری را جستجو کنید.</div>':'<div class="p-2 sr-muted">در حال دریافت مشتریان...</div>');try{const url=routes.customersSearch+(q.length>=2?('?q='+encodeURIComponent(q)):'');const r=await fetch(url,{signal:customerAbort.signal});if(!r.ok)throw new Error('HTTP '+r.status);if(req!==customerRequest)return;const data=await r.json();const rows=data.data||data.results||[];renderCustomerStatus(rows.length?rows.map(c=>`<div class="sr-result" role="option" tabindex="0" data-id="${c.id}" data-name="${esc(c.name||c.text)}" data-mobile="${esc(c.mobile||'')}" data-code="${esc(c.customer_code||c.code||'')}"><strong>${esc(c.name||c.text)}</strong><div class="small sr-muted">${esc(toPersianDigits(c.mobile||'بدون موبایل'))} | کد: ${esc(toPersianDigits(c.customer_code||c.code||c.id))}</div></div>`).join(''):'<div class="p-2 sr-muted">مشتری‌ای پیدا نشد.</div>')}catch(e){if(e.name==='AbortError')return;console.error('searchCustomers failed',e);renderCustomerStatus('<div class="p-2 text-danger">دریافت مشتریان با خطا مواجه شد.</div>')}}
function renderSelectedCustomer(){const label=$('#selectedCustomerLabel');if(!label)return;if(!state.customer.id){label.textContent='نام، موبایل یا کد مشتری را جستجو کنید.';return}label.innerHTML=`<span><strong>${esc(state.customer.name||'—')}</strong><br><span class="sr-muted">${esc(toPersianDigits(state.customer.mobile||'بدون موبایل'))} — کد: ${esc(toPersianDigits(state.customer.code||state.customer.id))}</span></span><button type="button" class="btn btn-link btn-sm p-0" id="clearCustomer">تغییر/حذف</button>`}
function resetInvoiceSelect(message='ابتدا مشتری را انتخاب کنید', disabled=true){const select=$('#invoiceSelect');if(!select)return;select.disabled=disabled;select.innerHTML=`<option value="">${esc(message)}</option>`;$('#invoiceSummary')&&($('#invoiceSummary').textContent='');$('#invoiceId')&&($('#invoiceId').value='');state.invoice=null}
function setSelectedCustomer(customer){const id=Number(customer?.id||0);if(!id){state.customer={id:null,name:'',mobile:'',code:''};$('#customerId')&&($('#customerId').value='');$('#customerSearch')&&($('#customerSearch').value='');state.items=[];renderItems();renderSelectedCustomer();resetInvoiceSelect();return}const changed=String(state.customer.id||'')!==String(id);state.customer={id:String(id),name:customer.name||customer.text||'',mobile:customer.mobile||'',code:customer.code||customer.customer_code||String(id)};$('#customerId')&&($('#customerId').value=state.customer.id);$('#customerSearch')&&($('#customerSearch').value=state.customer.name);renderSelectedCustomer();closeCustomerDropdown();if(changed){state.items=[];renderItems();resetInvoiceSelect('در حال دریافت فاکتورها...', true)}if(state.type==='internal_invoice')loadCustomerInvoices(state.customer.id)}
function selectCustomer(el){setSelectedCustomer({id:el.dataset.id,name:el.dataset.name,mobile:el.dataset.mobile,code:el.dataset.code})}
async function loadCustomerInvoices(customerId){customerId=String(customerId||state.customer.id||'');if(!customerId){resetInvoiceSelect();return}if(state.type!=='internal_invoice')return;if(invoiceAbort)invoiceAbort.abort();const req=++invoiceRequest;invoiceAbort=new AbortController();resetInvoiceSelect('در حال دریافت فاکتورها...', true);try{const r=await fetch(routes.customerInvoices.replace('__CUSTOMER__',encodeURIComponent(customerId)),{signal:invoiceAbort.signal});if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();if(req!==invoiceRequest||String(state.customer.id)!==String(customerId))return;const invoices=Array.isArray(data.invoices)?data.invoices:(Array.isArray(data.data)?data.data:[]);const select=$('#invoiceSelect');if(!select)return;select.disabled=false;if(!invoices.length){select.innerHTML='<option value="">فاکتور مجاز برای این مشتری پیدا نشد</option>';return}select.innerHTML='<option value="">انتخاب فاکتور</option>'+invoices.map(inv=>{const number=inv.number||inv.uuid||inv.id;const dateFa=inv.invoice_date_fa||inv.date_fa||fmtDate(inv.invoice_date||inv.date);const total=inv.total??inv.amount??0;const items=inv.items_count??0;const status=inv.status_label||inv.status||'';const summary=`فاکتور ${toPersianDigits(number)} | ${dateFa} | ${moneyText(total)} | ${toPersianDigits(items)} قلم | ${status}`;return `<option value="${esc(inv.id)}" data-summary="${esc(summary)}">فاکتور ${esc(toPersianDigits(number))} | ${esc(dateFa)} | ${moneyText(total)} | ${esc(status)} | ${toPersianDigits(items)} قلم</option>`}).join('');if(init.invoiceId&&String(state.customer.id)===String(customerId))select.value=init.invoiceId;renderInvoiceSummary()}catch(e){if(e.name==='AbortError')return;console.error('loadCustomerInvoices failed',e);resetInvoiceSelect('دریافت فاکتورها با خطا مواجه شد', true)}}
async function loadInvoices(){return loadCustomerInvoices(state.customer.id||$('#customerId')?.value)}
async function loadInvoiceItems(){const inv=$('#invoiceId')?.value;if(!inv){alert('ابتدا فاکتور را انتخاب کنید.');return}const body=$('#invoiceItemsBody');if(body)body.innerHTML='<tr><td colspan="8" class="text-center sr-muted">در حال دریافت اقلام...</td></tr>';try{const r=await fetch(routes.invoiceItems.replace('__INVOICE__',inv)+'?customer_id='+encodeURIComponent($('#customerId')?.value||''));if(!r.ok){let payload={};try{payload=await r.json()}catch(error){console.error('invalid invoice items response',error)}alert(payload.message||'خطا در دریافت اقلام فاکتور');return}const data=await r.json();if(body)body.innerHTML=(data.items||[]).map(it=>`<tr class="${it.disabled?'table-secondary':''}" data-text="${esc((it.product_name||'')+' '+(it.variant_name||'')+' '+(it.sku||''))}"><td><input type="checkbox" class="invoice-pick" ${it.disabled||state.items.some(x=>x.invoice_item_id===it.invoice_item_id)?'disabled':''} data-item='${esc(JSON.stringify(it))}'></td><td>${esc(it.product_name||'—')}</td><td>${esc(it.variant_name||'—')}</td><td>${esc(it.sku||it.barcode||'—')}</td><td>${fmt(it.quantity)}</td><td>${fmt(it.previously_returned)}</td><td>${fmt(it.returnable)}</td><td><strong>خالص واحد: ${fmt(it.net_refund_unit_price)}</strong><div class="small sr-muted">واحد فاکتور: ${fmt(it.historical_unit_price)} | تخفیف ردیف: ${fmt(it.line_discount)} | سهم تخفیف فاکتور: ${fmt(it.allocated_invoice_discount)} | خالص ردیف: ${fmt(it.net_refund_total)}</div></td></tr>`).join('')||'<tr><td colspan="8" class="text-center sr-muted">قلم قابل برگشتی وجود ندارد.</td></tr>'}catch(e){console.error('loadInvoiceItems failed',e);if(body)body.innerHTML='<tr><td colspan="8" class="text-center text-danger">دریافت اقلام فاکتور با خطا مواجه شد.</td></tr>'}}
async function loadCategories(parentId=null){const box=$('#categoryResults');if(box)box.innerHTML='<div class="p-2 sr-muted">در حال دریافت دسته‌بندی‌ها...</div>';try{const url=routes.categories+(parentId?('?parent_id='+parentId):'');const r=await fetch(url);if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();if(box)box.innerHTML=(data.data||[]).map(c=>`<button type="button" class="list-group-item list-group-item-action cat-pick" data-id="${c.id}" data-name="${esc(c.name)}" data-code="${esc(c.code||'')}"><strong>${esc(c.name)}</strong><div class="small sr-muted">${c.code?('کد '+esc(c.code)+' | '):''}${c.products_count} کالا</div></button>`).join('')||'<div class="sr-muted p-2">زیردسته‌ای وجود ندارد؛ محصولات همین دسته را ببینید.</div>'}catch(e){console.error('loadCategories failed',e);if(box)box.innerHTML='<div class="p-2 text-danger">دریافت دسته‌بندی‌ها با خطا مواجه شد.</div>'}}
async function loadCategoryProducts(q=''){const cat=state.selectedCategories.at(-1);if(!cat)return;if(categoryProductAbort)categoryProductAbort.abort();categoryProductAbort=new AbortController();const box=$('#categoryProductResults');if(box)box.innerHTML='<div class="p-2 sr-muted">در حال دریافت کالاها...</div>';try{const r=await fetch(routes.categoryProducts.replace('__CATEGORY__',cat.id)+(q?('?q='+encodeURIComponent(q)):''),{signal:categoryProductAbort.signal});if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();if(box)box.innerHTML=(data.data||[]).map(p=>`<button type="button" class="list-group-item list-group-item-action product-select" data-id="${p.id}"><strong>${esc(p.name)}</strong><div class="small sr-muted">${esc(p.code||'بدون کد')} | ${esc(p.category||'بدون دسته')} | ${p.variants_count} تنوع ${p.is_active?'':' | غیرفعال'} ${p.sales_enabled?'':' | فروش غیرفعال'}</div></button>`).join('')||'<div class="p-2 sr-muted">محصولی یافت نشد.</div>'}catch(e){if(e.name==='AbortError')return;console.error('loadCategoryProducts failed',e);if(box)box.innerHTML='<div class="p-2 text-danger">دریافت کالاها با خطا مواجه شد.</div>'}}
async function loadProductVariants(productId){const box=$('#variantCheckboxes');if(box)box.innerHTML='<div class="p-2 sr-muted">در حال دریافت تنوع‌ها...</div>';try{const r=await fetch(routes.productVariants.replace('__PRODUCT__',productId));if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();const product=data.product||{};state.selectedProducts[productId]=product;if(box)box.innerHTML=`<div class="mb-2"><strong>${esc(product.name||'محصول')}</strong><div class="small sr-muted">کد: ${esc(product.code||'—')}</div></div>`+(data.variants||[]).map(v=>{const key=String(v.id), checked=state.selectedVariants.has(key);return `<label class="d-block border rounded p-2 mb-1 ${checked?'bg-light':''}"><input type="checkbox" class="form-check-input ms-1 variant-pick" data-product-id="${productId}" data-product-name="${esc(product.name||'')}" data-variant='${esc(JSON.stringify(v))}' ${checked?'checked':''}> <strong>${esc(v.name||'تنوع اصلی')}</strong><div class="small sr-muted">طرح/مدل: ${esc(v.variety_name||'—')} | SKU: ${esc(v.sku||'—')} | موجودی: ${fmt(v.stock)} | خرید: ${fmt(v.buy_price)} | فروش: ${fmt(v.sell_price)} ${v.is_active?'':' | غیرفعال'} ${v.sales_enabled?'':' | فروش غیرفعال'}</div></label>`}).join('')+`<div class="sticky-bottom bg-white border-top pt-2 mt-2"><span id="variantSelectedCount">${state.selectedVariants.size}</span> تنوع انتخاب‌شده <button type="button" class="btn btn-primary btn-sm float-start" id="addPickedVariants">افزودن به برگشتی</button></div>`}catch(e){console.error('loadProductVariants failed',e);if(box)box.innerHTML='<div class="p-2 text-danger">دریافت تنوع‌های کالا با خطا مواجه شد.</div>'}}
async function searchProducts(q){if(productAbort)productAbort.abort();const box=$('#productResults');if((q||'').length<2){if(box)box.innerHTML='<div class="p-2 sr-muted">برای جستجو حداقل ۲ کاراکتر وارد کنید.</div>';return}productAbort=new AbortController();if(box)box.innerHTML='<div class="p-2 sr-muted">در حال جستجوی کالا...</div>';try{const r=await fetch(routes.productsSearch+'?q='+encodeURIComponent(q),{signal:productAbort.signal});if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();if(box)box.innerHTML=(data.results||[]).map(p=>`<button type="button" class="list-group-item list-group-item-action product-select" data-id="${p.id}"><strong>${esc(p.text)}</strong><div class="small sr-muted">${esc(p.category||'بدون دسته')} | SKU: ${esc(p.sku||'—')} | موجودی: ${fmt(p.stock)} ${p.is_active?'':' | غیرفعال'} ${p.sales_enabled?'':' | فروش غیرفعال'}</div></button>`).join('')||'<div class="p-2 sr-muted">نتیجه‌ای یافت نشد.</div>'}catch(e){if(e.name==='AbortError')return;console.error('searchProducts failed',e);if(box)box.innerHTML='<div class="p-2 text-danger">جستجوی کالا با خطا مواجه شد.</div>'}}
function addSelectedVariants(){let added=0;state.selectedVariants.forEach(({variant,productId,productName})=>{if(state.items.some(i=>String(i.product_variant_id)===String(variant.id)))return;state.items.push({item_source:'existing_product',product_id:productId,product_variant_id:variant.id,product_name:productName,variant_name:variant.name,sku:variant.sku,barcode:variant.barcode,return_quantity:1,item_condition:'healthy',destination_warehouse_id:state.defaultDestinationWarehouseId||defaultWhFor('healthy'),refund_unit_price:0,refund_amount:0,purchase_price:variant.buy_price,sell_price:variant.sell_price,current_sell_price:variant.sell_price});added++});renderItems();if(added)bootstrap.Modal.getInstance($('#sazehItemsModal'))?.hide();else alert('تنوع جدیدی برای افزودن وجود ندارد یا موارد تکراری هستند.')}
function defaultWhFor(condition){const warehouses=init.warehouses||[];const isReturn=w=>String(w.type||'').toLowerCase()==='return'||String(w.name||'').includes('مرجوع');const match=condition==='damaged'?warehouses.find(isReturn):(warehouses.find(w=>!isReturn(w))||warehouses[0]);return match?.id||''}

const np={categoryPath:[],selectedModels:new Set(),pickedVariants:new Set(),lastVariants:[],userTouchedVariants:false,showAllTags:false,designDrafts:[],editingProductUuid:null};
function boolInt(value){return value===true||value===1||value==='1'||value==='true'?1:0}
function npModels(){return init.modelLists||[]}
function npCategories(){return init.categories||[]}
function npChildren(parent){return npCategories().filter(c=>String(c.parent_id||'')===String(parent||''))}
function npCategoryById(id){return npCategories().find(c=>String(c.id)===String(id))}
function npSelectedCategory(){return np.categoryPath.length?npCategoryById(np.categoryPath[np.categoryPath.length-1]):null}
function npModelById(id){return npModels().find(m=>String(m.id)===String(id))}
function npInit(){if(!$('#npCategoryLevels'))return;const brand=$('#npModelBrand');if(brand&&brand.options.length<=1){[...new Set(npModels().map(m=>m.brand).filter(Boolean))].sort().forEach(b=>brand.insertAdjacentHTML('beforeend',`<option value="${esc(b)}">${esc(b)}</option>`))}npRenderCategoryLevels();npRenderModels();npRenderDesigns();npRenderPreview()}
function npRenderCategoryLevels(){const wrap=$('#npCategoryLevels');if(!wrap)return;wrap.innerHTML='';let parent=null;let level=0;while(true){const children=npChildren(parent);if(!children.length&&level>0)break;const selected=np.categoryPath[level]||'';const col=document.createElement('div');col.className='col-md-6 tree-level';col.innerHTML=`<label class="form-label">${level===0?'دسته اصلی':'زیر‌دسته '+level}</label><select class="form-select form-select-sm np-category-level" data-level="${level}"><option value="">انتخاب کنید</option>${children.map(c=>`<option value="${c.id}" data-code="${esc(c.code||'')}" ${String(c.id)===String(selected)?'selected':''}>${esc(c.name)} ${c.code?'('+esc(c.code)+')':''}</option>`).join('')}</select>`;wrap.appendChild(col);if(!selected)break;parent=selected;level++;if(level>8)break}npUpdateBreadcrumb()}
function npUpdateBreadcrumb(){const path=np.categoryPath.map(id=>npCategoryById(id)).filter(Boolean);$('#npCategoryBreadcrumb')&&($('#npCategoryBreadcrumb').textContent=path.length?path.map(c=>c.name).join(' > '):'دسته‌بندی انتخاب نشده است');const cat=path[path.length-1];const seq=toEnglishDigits($('#npSeqPreview')?.textContent||'0001');if(!cat){$('#npCodeHint')&&($('#npCodeHint').textContent='پس از انتخاب دسته‌بندی، کد کالا نمایش داده می‌شود.');$('#npProductCodePreview')&&($('#npProductCodePreview').textContent='—');$('#npVariantCodePreview')&&($('#npVariantCodePreview').textContent='—');return}$('#npCodeHint')&&($('#npCodeHint').textContent='کد کالا بر اساس دسته‌بندی نهایی ساخته می‌شود.');const code=(cat.code||'00').toString().padStart(2,'0').slice(0,2)+seq;$('#npSeqPreview')&&($('#npSeqPreview').textContent=toPersianDigits(seq));$('#npProductCodePreview')&&($('#npProductCodePreview').textContent=toPersianDigits(code));$('#npVariantCodePreview')&&($('#npVariantCodePreview').textContent=toPersianDigits(code+'MMMDD'))}
function updateNewProductFeaturePanels(){const useModels=Boolean($('#npUseModels')?.checked),useDesigns=Boolean($('#npUseDesigns')?.checked);$('#npModelPanel')?.classList.toggle('d-none',!useModels);$('#npDesignPanel')?.classList.toggle('d-none',!useDesigns)}
function syncNewProductLayout(){updateNewProductFeaturePanels()}
function npRenderModels(){syncNewProductLayout();const panel=$('#npModelPanel');if(!panel)return;panel.classList.toggle('d-none',!$('#npUseModels').checked);const brand=$('#npModelBrand').value, q=($('#npModelSearch').value||'').toLowerCase();const list=npModels().filter(m=>(!brand||m.brand===brand)&&(!q||String(m.model_name+' '+m.code+' '+m.brand).toLowerCase().includes(q)));$('#npModelList').innerHTML=list.map(m=>`<label class="d-block border rounded p-2 mb-1"><input type="checkbox" class="form-check-input ms-1 np-model-check" value="${m.id}" ${np.selectedModels.has(String(m.id))?'checked':''}> <strong>${esc(m.model_name||'')}</strong><div class="small sr-muted">${esc(m.brand||'—')} | کد: ${esc(toPersianDigits(m.code||'—'))}</div></label>`).join('')||'<div class="sr-muted small">مدلی برای این فیلتر وجود ندارد.</div>';$('#npSelectedModelCount').textContent=np.selectedModels.size;{const models=[...np.selectedModels].map(id=>npModelById(id)).filter(Boolean);const visible=np.showAllTags?models:models.slice(0,6);$('#npModelTags').innerHTML=visible.map(m=>`<span class="picker-tag">${esc(m.brand)} / ${esc(m.model_name)} (${esc(toPersianDigits(m.code||'—'))})</span>`).join('')+(models.length>6&&!np.showAllTags?`<button type="button" class="btn btn-link btn-sm p-0" id="npShowAllModelTags">+ ${toPersianDigits(models.length-6)} مدل دیگر</button>`:'')}}
function npCaptureDesignDrafts(){const inputs=$$('.np-design-name');if(inputs.length)np.designDrafts=inputs.map(input=>input.value)}
function npRenderDesigns(){syncNewProductLayout();npCaptureDesignDrafts();const on=$('#npUseDesigns')?.checked;$('#npDesignPanel')?.classList.toggle('d-none',!on);const wrap=$('#npDesignRows');if(!wrap||!on)return;let count=Math.max(1,Math.min(99,Number($('#npDesignCount').value||1)));$('#npDesignCount').value=count;wrap.innerHTML='';for(let i=1;i<=count;i++){wrap.insertAdjacentHTML('beforeend',`<div class="design-note-item"><span class="badge bg-light text-dark">طرح ${i}</span><input class="form-control form-control-sm np-design-name np-field" data-index="${i}" value="${esc(np.designDrafts[i-1]||'')}" placeholder="مثلاً مشکی"></div>`)}}
function npDesigns(){return $('#npUseDesigns')?.checked?$$('.np-design-name').map((i,idx)=>({index:idx+1,name:i.value.trim()})).filter(d=>d.name):[]}
function npSyncPrice(id){const key=id==='npPurchase'?'purchase':id==='npSell'?'sell':'refund';const value=moneyToInteger($('#'+id)?.value||'');state.newProduct.prices[key]=value;const input=$('#'+id);if(input)input.value=value===null?'':fmt(value)}
function npPrice(id){const key=id==='npPurchase'?'purchase':id==='npSell'?'sell':'refund';return state.newProduct.prices[key]}
function npVariantCombos(){if(!npSelectedCategory())return[];const useM=$('#npUseModels')?.checked,useD=$('#npUseDesigns')?.checked;const models=useM?[...np.selectedModels].map(id=>npModelById(id)).filter(Boolean):[null];const designs=useD?npDesigns():[{index:0,name:''}];const base=($('#npName')?.value||'کالای جدید').trim();const cat=npSelectedCategory();const seq=$('#npSeqPreview')?.textContent||'0001';const productCode=((cat?.code||'00').toString().padStart(2,'0').slice(0,2)+toEnglishDigits(seq));let rows=[];models.forEach(m=>designs.forEach(d=>{const key='model:'+(m?.id||'none')+'|design:'+(d.index||'none');const modelCode=String(m?.code||'000').replace(/\D/g,'').padStart(3,'0').slice(0,3);const designCode=String(d.index||0).padStart(2,'0');rows.push({key,model:m,design:d,display_name:[base,m?.model_name,d.name].filter(Boolean).join(' / '),preview_code:productCode+modelCode+designCode})}));return rows.length?rows:[]}
function npValidate(){const errs=[];const setErr=(sel,msg)=>{const el=$(sel);if(el)el.textContent=msg||'';if(msg)errs.push(msg)};setErr('#npCategoryError',npSelectedCategory()?'':'دسته‌بندی نهایی کالا را انتخاب کنید.');if($('#npUseModels')?.checked&&np.selectedModels.size<1)errs.push('حداقل یک مدل انتخاب کنید.');if($('#npUseDesigns')?.checked){const c=Number($('#npDesignCount').value||0), d=npDesigns();setErr('#npDesignError',(c<1||d.length!==c)?'نام همه طرح‌ها را کامل کنید.':'')}else setErr('#npDesignError','');['npPurchase','npSell','npRefund'].forEach(id=>{const value=npPrice(id);const required=id==='npRefund';const msg=(value===null||value<0||(required&&value<1))?'قیمت معتبر وارد کنید.':'';setErr(`[data-price-error="${id}"]`,msg)});const selected=npVariantCombos().filter(v=>np.pickedVariants.has(v.key)).length;setErr('#npVariantError',selected<1?'حداقل یک تنوع باید انتخاب شود.':'');if(!$('#npName')?.value.trim())errs.push('نام کالا الزامی است.');$('#npErrors')&&($('#npErrors').innerHTML='');$('#addNewProductRow')&&($('#addNewProductRow').disabled=errs.length>0);return errs.length===0}
