<td><button class="btn btn-sm btn-outline-danger rm" data-i="${i}" type="button">حذف</button></td>`;tb.appendChild(tr);const mobilePrice=state.type==='internal_invoice'?`<div class="my-1">قیمت تاریخی خالص: ${internalPriceDetails(it)}</div>`:`<div class="my-2">${sazehPriceField(it,i,'mobile-price')}</div>`;$('#mobileItems').insertAdjacentHTML('beforeend',`<div class="border rounded p-2 mb-2"><div class="d-flex justify-content-between"><strong>${esc(rowName(it))}</strong><button class="btn btn-sm btn-outline-danger rm" data-i="${i}" type="button">حذف</button></div><div class="small sr-muted">تعداد: <input class="form-control form-control-sm qty my-1" data-i="${i}" type="number" min="1" max="${max}" value="${it.return_quantity}">${mobilePrice} وضعیت: <select class="form-select form-select-sm cond my-1" data-i="${i}"><option value="healthy" ${it.item_condition==='healthy'?'selected':''}>سالم</option><option value="damaged" ${it.item_condition==='damaged'?'selected':''}>معیوب / مرجوعی</option></select> مقصد: <select class="form-select form-select-sm wh my-1" data-i="${i}">${whOptions(it.destination_warehouse_id)}</select> مبلغ کل: <strong data-row-amount="${i}">${fmt(it.refund_amount)}</strong> ریال</div></div>`)});$$('.internal-col').forEach(el=>el.classList.toggle('d-none',state.type==='sazeh_hesab'));summary();}
