$('#invoiceSelect').addEventListener('change',e=>{$('#invoiceId').value=e.target.value;state.invoice=e.target.value;state.items=[];renderItems();renderInvoiceSummary()});$('#openAddItem').onclick=()=>{if(state.type==='internal_invoice'){loadInvoiceItems().then(()=>new bootstrap.Modal($('#internalItemsModal')).show())}else{loadCategories(null);new bootstrap.Modal($('#sazehItemsModal')).show()}};$('#addSelectedInvoiceItems').onclick=()=>{$$('.invoice-pick:checked').forEach(cb=>{const it=JSON.parse(cb.dataset.item);if(state.items.some(x=>x.invoice_item_id===it.invoice_item_id))return;state.items.push({item_source:'invoice_item',invoice_item_id:it.invoice_item_id,product_id:it.product_id,product_variant_id:it.variant_id,product_name:it.product_name,variant_name:it.variant_name,sku:it.sku,barcode:it.barcode,sold_quantity:it.quantity,previously_returned:it.previously_returned,previously_returned_amount:it.previously_returned_amount,returnable:it.returnable,return_quantity:1,item_condition:'healthy',destination_warehouse_id:state.defaultDestinationWarehouseId||defaultWhFor('healthy'),historical_unit_price:it.historical_unit_price,line_discount:it.line_discount,allocated_invoice_discount:it.allocated_invoice_discount,net_refund_total:it.net_refund_total,refund_unit_price:it.net_refund_unit_price,refund_amount:it.net_refund_unit_price})});renderItems();bootstrap.Modal.getInstance($('#internalItemsModal')).hide()};$('#invoiceItemFilter').addEventListener('input',e=>{$$('#invoiceItemsBody tr').forEach(tr=>tr.classList.toggle('d-none',!tr.dataset.text.includes(e.target.value)))});$('#categoryResults')?.addEventListener('click',e=>{const el=e.target.closest('.cat-pick');if(!el)return;state.selectedCategories.push({id:el.dataset.id,name:el.dataset.name});$('#categoryPath').textContent=state.selectedCategories.map(c=>c.name).join(' > ');loadCategories(el.dataset.id);loadCategoryProducts();$('#variantCheckboxes').textContent='محصول را انتخاب کنید.'});$('#categoryProductSearch')?.addEventListener('input',e=>{clearTimeout(productTimer);productTimer=setTimeout(()=>loadCategoryProducts(e.target.value),300)});$('#productSearch')?.addEventListener('input',e=>{clearTimeout(productTimer);productTimer=setTimeout(()=>searchProducts(e.target.value),300)});document.addEventListener('click',e=>{const ps=e.target.closest('.product-select');if(ps)loadProductVariants(ps.dataset.id);if(e.target.id==='addPickedVariants')addSelectedVariants();if(e.target.classList.contains('rm')){state.items.splice(Number(e.target.dataset.i),1);renderItems()}});document.addEventListener('change',e=>{if(e.target.classList.contains('variant-pick')){const v=JSON.parse(e.target.dataset.variant), key=String(v.id);e.target.checked?state.selectedVariants.set(key,{variant:v,productId:e.target.dataset.productId,productName:e.target.dataset.productName}):state.selectedVariants.delete(key);$('#variantSelectedCount')&&($('#variantSelectedCount').textContent=state.selectedVariants.size)}});document.addEventListener('input',e=>{if(e.target.classList.contains('qty')){const i=Number(e.target.dataset.i),it=state.items[i];it.return_quantity=Number(e.target.value||1);updateRowAmount(i)}if(e.target.classList.contains('price')){const i=Number(e.target.dataset.i),it=state.items[i];it.refund_unit_price=rawNumber(e.target.value);updateRowAmount(i)}});document.addEventListener('focusin',e=>{if(e.target.classList.contains('price'))e.target.value=String(state.items[Number(e.target.dataset.i)]?.refund_unit_price||'')});document.addEventListener('focusout',e=>{if(e.target.classList.contains('price'))e.target.value=fmt(state.items[Number(e.target.dataset.i)]?.refund_unit_price||0)});document.addEventListener('change',e=>{if(e.target.classList.contains('cond')){const i=Number(e.target.dataset.i),it=state.items[i];it.item_condition=e.target.value;if(!it.destination_touched)it.destination_warehouse_id=state.defaultDestinationWarehouseId||defaultWhFor(e.target.value);renderItems()}if(e.target.classList.contains('wh')){const it=state.items[Number(e.target.dataset.i)];it.destination_warehouse_id=e.target.value;markManualDestination(it);renderItems()}});$('#defaultWarehouse').addEventListener('change',e=>{state.defaultDestinationWarehouseId=e.target.value;state.items.forEach(it=>{if(!it.destination_touched&&!it.destination_warehouse_id)it.destination_warehouse_id=e.target.value});renderItems()});$('#clearForm').onclick=()=>{if(confirm('فرم پاک شود؟')){state.items=[];renderItems()}};$('#applyButton').onclick=e=>{if(!confirm('ثبت نهایی موجودی و بستانکاری مشتری را تغییر می‌دهد. ادامه می‌دهید؟'))e.preventDefault()};syncExternalDateDisplay();$('#externalInvoiceDateFa')?.addEventListener('input',e=>syncExternalDateFromVisible(false));$('#salesReturnForm')?.addEventListener('submit',e=>{renderItems();if(!state.defaultDestinationWarehouseId){e.preventDefault();$('#defaultWarehouse')?.focus();alert('برای ادامه یک انبار مقصد واحد انتخاب کنید.');return}if(state.type==='sazeh_hesab'&&!syncExternalDateFromVisible(true)){e.preventDefault();$('#externalInvoiceDateFa')?.focus()}});applySourceType($('#sourceTypeInput')?.value || 'internal_invoice', {initial:true});if(init.customerId)loadInvoices();renderItems();
document.addEventListener('input',e=>{if(!e.target.classList.contains('price'))return;const i=Number(e.target.dataset.i);document.querySelectorAll(`.price[data-i="${i}"]`).forEach(input=>{if(input!==e.target)input.value=fmt(state.items[i]?.refund_unit_price||0)})});
$('#salesReturnForm')?.addEventListener('submit',e=>{if(state.type!=='sazeh_hesab')return;const invalidIndex=state.items.findIndex(item=>Number(item.refund_unit_price||0)<1);if(invalidIndex<0)return;e.preventDefault();const field=document.querySelector(`.price[data-i="${invalidIndex}"]`);field?.focus();alert('مبلغ واحد برگشت هر ردیف سازه‌حساب باید حداقل ۱ ریال باشد.')});
$('#salesReturnForm')?.addEventListener('submit',e=>{try{syncCompactItemsPayload(true)}catch(error){e.preventDefault();alert(error.message||'اطلاعات اقلام برگشتی ناقص است.')}});
document.addEventListener('click',e=>{const edit=e.target.closest('.edit-new-product');if(edit)npEditGroup(edit.dataset.uuid)});
function clearServerErrors(){const box=$('#formErrorSummary');box?.classList.add('d-none');if(box)box.textContent='';$$('[data-field-error]').forEach(el=>el.textContent='')}
function showServerErrors(errors={}){clearServerErrors();const messages=Object.values(errors).flat().filter(Boolean),box=$('#formErrorSummary');if(box){box.textContent=messages.length?messages.join(' '):'اطلاعات فرم نیاز به اصلاح دارد.';box.classList.remove('d-none')}Object.entries(errors).forEach(([key,value])=>{const field=key.split('.')[0],inline=document.querySelector(`[data-field-error="${CSS.escape(field)}"]`);if(inline)inline.textContent=Array.isArray(value)?value[0]:value});const firstKey=Object.keys(errors)[0]?.split('.')[0],firstField=firstKey?document.querySelector(`[name="${CSS.escape(firstKey)}"]`):null;(firstField||box)?.scrollIntoView({behavior:'smooth',block:'center'});firstField?.focus()}
let ajaxSubmitting=false;
$('#salesReturnForm')?.addEventListener('submit',async e=>{if(e.defaultPrevented||ajaxSubmitting)return;e.preventDefault();const form=e.currentTarget;clearServerErrors();const selectedSource=form.querySelector('input[name="source_choice"]:checked'),allowedSources=['internal_invoice','sazeh_hesab'];if(!selectedSource){showServerErrors({source_type:['نوع منبع برگشت را انتخاب کنید.']});return}const selectedSourceValue=selectedSource.value.trim();if(!allowedSources.includes(selectedSourceValue)){showServerErrors({source_type:['نوع منبع برگشت معتبر نیست.']});return}const actionUrl=form.getAttribute('action');if(!actionUrl){showServerErrors({form:['مسیر ثبت برگشت از فروش معتبر نیست.']});return}let payload;try{syncCompactItemsPayload(true);const data=new FormData(form,e.submitter);payload={};data.forEach((value,key)=>{payload[key]=value})}catch(error){showServerErrors({items_payload:[error.message||'اطلاعات اقلام برگشتی ناقص است.']});return}ajaxSubmitting=true;const buttons=$$('button[type="submit"]',form);buttons.forEach(button=>button.disabled=true);try{const response=await fetch(actionUrl,{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},body:JSON.stringify(payload)});const result=await response.json().catch(()=>({}));if(response.status===422){showServerErrors(result.errors);return}if(response.status===419){showServerErrors({session:['نشست شما منقضی شده است. صفحه را در یک تب دیگر تازه کنید؛ اطلاعات این فرم حفظ شده است.']});return}if(response.status===409){showServerErrors({document:[result.message||'این سند هم‌زمان تغییر کرده است. پیش از ثبت دوباره، وضعیت سند را بررسی کنید.']});return}if(!response.ok)throw new Error(result.message||'ثبت سند انجام نشد.');if(result.redirect_url)window.location.assign(result.redirect_url);else if(result.message){const box=$('#formErrorSummary');box.textContent=result.message;box.classList.remove('d-none','alert-danger');box.classList.add('alert-success')}}catch(error){showServerErrors({server:[error.message||'ارتباط با سرور برقرار نشد. دوباره تلاش کنید.']})}finally{ajaxSubmitting=false;buttons.forEach(button=>button.disabled=false)}});
} catch (error) {
    console.error('Sales return create initialization failed', error);
}
});
